import os
import torch


class Config:
    """
    Global configuration for the Scaled Hybrid Geometric-Attention Network (HGA-Net) pipeline.
    Contains paths, model hyperparameters, training settings, and physical constants.
    """

    # --------------------------------------------------------------------------
    # 1. File System Paths
    # --------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_9"

    # Metadata paths (generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Raw structures directory
    STRUCTURES_DIR = os.path.join(INPUT_DIR, "structures")

    # Caching paths (Parquet/NPZ for speed)
    # Using .npz for graph data structures usually
    CACHE_TRAIN_PATH = os.path.join(WORKING_DIR, "cached_train.npz")
    CACHE_VAL_PATH = os.path.join(WORKING_DIR, "cached_val.npz")
    CACHE_TEST_PATH = os.path.join(WORKING_DIR, "cached_test.npz")

    # Model and Submission paths
    MODEL_SAVE_PATH = os.path.join(WORKING_DIR, "best_model.pt")
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # --------------------------------------------------------------------------
    # 2. Reproducibility
    # --------------------------------------------------------------------------
    SEED = 42

    # --------------------------------------------------------------------------
    # 3. Data Processing & Physical Constants
    # --------------------------------------------------------------------------
    # Atom mapping for CHAMPS dataset (H, C, N, O, F)
    ATOM_TYPES = {"H": 0, "C": 1, "N": 2, "O": 3, "F": 4}
    NUM_ATOM_TYPES = len(ATOM_TYPES)

    # Scalar Coupling Types
    COUPLING_TYPES = ["1JHC", "2JHH", "1JHN", "2JHN", "2JHC", "3JHH", "3JHC", "3JHN"]
    NUM_COUPLING_TYPES = len(COUPLING_TYPES)

    # Geometric Graph Construction
    CUTOFF = 5.0  # Angstroms, spatial cutoff for connectivity

    # --------------------------------------------------------------------------
    # 4. Model Hyperparameters (HGA-Net)
    # --------------------------------------------------------------------------
    # Backbone: Directional Message Passing
    HIDDEN_DIM = 256  # High capacity (192 or 256 suggested)
    NUM_LAYERS = 6  # Number of interaction layers

    # Geometric Basis Functions
    NUM_RBF = 50  # Radial Basis Functions for distance
    NUM_SBF = 7  # Spherical Basis Functions for angles

    # Global Interaction: Graph Transformer
    NUM_HEADS = 8  # Attention heads for the global transformer

    # Regularization & Architecture
    USE_DROPOUT = False  # Strictly avoid dropout for regression precision
    ACTIVATION = "swish"  # SiLU/Swish activation

    # --------------------------------------------------------------------------
    # 5. Training Hyperparameters
    # --------------------------------------------------------------------------
    # Optimization
    BATCH_SIZE = 96  # Tuned for A100 40GB with deep geometric model
    EPOCHS = 50  # Extended horizon for convergence
    LEARNING_RATE = 5e-4  # Initial learning rate
    WEIGHT_DECAY = 1e-5  # Regularization

    # Scheduler
    WARMUP_EPOCHS = 3  # Linear warmup duration
    MIN_LR = 1e-6  # Cosine annealing minimum

    # Gradient Clipping
    MAX_GRAD_NORM = 1.0

    # --------------------------------------------------------------------------
    # 6. Runtime / Hardware
    # --------------------------------------------------------------------------
    NUM_WORKERS = 12  # Utilizing available vCPUs
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging control
    # Set DEBUG = True to run on a small subset for rapid testing
    DEBUG = False
    DEBUG_SUBSET_SIZE = 5000

    @classmethod
    def setup(cls):
        """
        Initialize the working environment.
        Creates necessary directories for caching and outputs.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)


# Automatically setup directories when config is imported
Config.setup()
